import{_ as n,a0 as r,w as o,s as d,ao as p,I as l,x as s,a1 as e,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"树莓派 3 的新手指南 | LCTT x X-CMD","titleTemplate":false,"description":"树莓派 3 的新手指南 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"树莓派 3 的新手指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"树莓派 3 的新手指南 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20170502 A beginner-s guide to Raspberry Pi 3","title":"树莓派 3 的新手指南","tag":"201801","desc":""},"relativePath":"201801/20170502 A beginner-s guide to Raspberry Pi 3.md","filePath":"[post].md"}'),g={name:"201801/20170502 A beginner-s guide to Raspberry Pi 3.md"};function h(u,i,b,k,m,f){const t=r("Link");return o(),d("div",null,[i[22]||(i[22]=p('<h1 id="树莓派-3-的新手指南" tabindex="-1">树莓派 3 的新手指南 <a class="header-anchor" href="#树莓派-3-的新手指南" aria-label="Permalink to “树莓派 3 的新手指南”">​</a></h1><blockquote><p>这个教程将帮助你入门<ruby>树莓派 3<rt>Raspberry Pi 3</rt></ruby>。</p></blockquote><p><img src="https://images.techhive.com/images/article/2017/03/raspberry2-100711632-large.jpeg" alt=""></p><p>这篇文章是我的使用树莓派 3 创建新项目的每周系列文章的一部分。该系列的这个第一篇文章专注于入门，它主要讲安装 Raspbian 和 PIXEL 桌面，以及设置网络和其它的基本组件。</p><h3 id="你需要" tabindex="-1">你需要： <a class="header-anchor" href="#你需要" aria-label="Permalink to “你需要：”">​</a></h3><ul><li>一台树莓派 3</li><li>一个 5v 2mAh 带 USB 接口的电源适配器</li><li>至少 8GB 容量的 Micro SD 卡</li><li>Wi-Fi 或者以太网线</li><li>散热片</li><li>键盘和鼠标</li><li>一台 PC 显示器</li><li>一台用于准备 microSD 卡的 Mac 或者 PC</li></ul><p>现在有很多基于 Linux 操作系统可用于树莓派，你可以直接安装它，但是，如果你是第一次接触树莓派，我推荐使用 NOOBS，它是树莓派官方的操作系统安装器，它安装操作系统到该设备的过程非常简单。</p>',7)),l("p",null,[i[1]||(i[1]=s("在你的电脑上从 ",-1)),e(t,{href:"https://www.raspberrypi.org/downloads/noobs/"},{default:a(()=>[...i[0]||(i[0]=[s("这个链接",-1)])]),_:1}),i[2]||(i[2]=s(" 下载 NOOBS。它是一个 zip 压缩文件。如果你使用的是 MacOS，可以直接双击它，MacOS 会自动解压这个文件。如果你使用的是 Windows，右键单击它，选择“解压到这里”。",-1))]),i[23]||(i[23]=p('<p>如果你运行的是 Linux 桌面，如何去解压 zip 文件取决于你的桌面环境，因为，不同的桌面环境下解压文件的方法不一样，但是，使用命令行可以很容易地完成解压工作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ unzip NOOBS.zip</span></span></code></pre></div><p>不管它是什么操作系统，打开解压后的文件，你看到的应该是如下图所示的样子：</p><p><img src="https://images.techhive.com/images/article/2017/03/content-100711633-large.jpg" alt="content"></p><p>现在，在你的 PC 上插入 Micro SD 卡，将它格式化成 FAT32 格式的文件系统。在 MacOS 上，使用磁盘实用工具去格式化 Micro SD 卡：</p><p><img src="https://images.techhive.com/images/article/2017/03/format-100711635-large.jpg" alt="format"></p>',6)),l("p",null,[i[4]||(i[4]=s("在 Windows 上，只需要右键单击这个卡，然后选择“格式化”选项。如果是在 Linux 上，不同的桌面环境使用不同的工具，就不一一去讲解了。在这里我写了一个教程，",-1)),e(t,{href:"http://www.cio.com/article/3176034/linux/how-to-format-an-sd-card-in-linux.html"},{default:a(()=>[...i[3]||(i[3]=[s("在 Linux 上使用命令行界面",-1)])]),_:1}),i[5]||(i[5]=s(" 去格式化 SD 卡为 Fat32 文件系统。",-1))]),i[24]||(i[24]=p('<p>在你的卡格式成了 FAT32 格式的文件系统后，就可以去拷贝下载的 NOOBS 目录的内容到这个卡的根目录下。如果你使用的是 MacOS 或者 Linux，可以使用 <code>rsync</code> 将 NOOBS 的内容传到 SD 卡的根目录中。在 MacOS 或者 Linux 中打开终端应用，然后运行如下的 rsync 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rsync -avzP /path_of_NOOBS /path_of_sdcard</span></span></code></pre></div><p>一定要确保选择了 SD 卡的根目录，在我的案例中（在 MacOS 上），它是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rsync -avzP /Users/swapnil/Downloads/NOOBS_v2_2_0/ /Volumes/U/</span></span></code></pre></div><p>或者你也可以拷贝粘贴 NOOBS 目录中的内容。一定要确保将 NOOBS 目录中的内容全部拷贝到 Micro SD 卡的根目录下，千万不能放到任何的子目录中。</p><p>现在可以插入这张 MicroSD 卡到树莓派 3 中，连接好显示器、键盘鼠标和电源适配器。如果你拥有有线网络，我建议你使用它，因为有线网络下载和安装操作系统更快。树莓派将引导到 NOOBS，它将提供一个供你去选择安装的分发版列表。从第一个选项中选择 Raspbian，紧接着会出现如下图的画面。</p><p><img src="https://images.techhive.com/images/article/2017/03/raspi-config-100711634-large.jpg" alt="raspi config"></p><p>在你安装完成后，树莓派将重新启动，你将会看到一个欢迎使用树莓派的画面。现在可以去配置它，并且去运行系统更新。大多数情况下，我们都是在没有外设的情况下使用树莓派的，都是使用 SSH 基于网络远程去管理它。这意味着你不需要为了管理树莓派而去为它接上鼠标、键盘和显示器。</p><p>开始使用它的第一步是，配置网络（假如你使用的是 Wi-Fi）。点击顶部面板上的网络图标，然后在出现的网络列表中，选择你要配置的网络并为它输入正确的密码。</p><p><img src="https://images.techhive.com/images/article/2017/03/wireless-100711636-large.jpeg" alt="wireless"></p><p>恭喜您，无线网络的连接配置完成了。在进入下一步的配置之前，你需要找到你的网络为树莓派分配的 IP 地址，因为远程管理会用到它。</p><p>打开一个终端，运行如下的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ifconfig</span></span></code></pre></div><p>现在，记下这个设备的 <code>wlan0</code> 部分的 IP 地址。它一般显示为 “inet addr”。</p><p>现在，可以去启用 SSH 了，在树莓派上打开一个终端，然后打开 <code>raspi-config</code> 工具。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo raspi-config</span></span></code></pre></div><p>树莓派的默认用户名和密码分别是 “pi” 和 “raspberry”。在上面的命令中你会被要求输入密码。树莓派配置工具的第一个选项是去修改默认密码，我强烈推荐你修改默认密码，尤其是你基于网络去使用它的时候。</p><p>第二个选项是去修改主机名，如果在你的网络中有多个树莓派时，主机名用于区分它们。一个有意义的主机名可以很容易在网络上识别每个设备。</p><p>然后进入到接口选项，去启用摄像头、SSH、以及 VNC。如果你在树莓派上使用了一个涉及到多媒体的应用程序，比如，家庭影院系统或者 PC，你也可以去改变音频输出选项。缺省情况下，它的默认输出到 HDMI 接口，但是，如果你使用外部音响，你需要去改变音频输出设置。转到树莓派配置工具的高级配置选项，选择音频，然后选择 “3.5mm” 作为默认输出。</p><p>[小提示：使用箭头键去导航，使用回车键去选择]</p><p>一旦应用了所有的改变， 树莓派将要求重新启动。你可以从树莓派上拔出显示器、鼠标键盘，以后可以通过网络来管理它。现在可以在你的本地电脑上打开终端。如果你使用的是 Windows，你可以使用 Putty 或者去读我的文章 - 怎么在 Windows 10 上安装 Ubuntu Bash。</p><p>在你的本地电脑上输入如下的 SSH 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh pi@IP_ADDRESS_OF_Pi</span></span></code></pre></div><p>在我的电脑上，这个命令是这样的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh pi@10.0.0.161</span></span></code></pre></div>',25)),l("p",null,[i[7]||(i[7]=s("输入它的密码，你登入到树莓派了！现在你可以从一台远程电脑上去管理你的树莓派。如果你希望通过因特网去管理树莓派，可以去阅读我的文章 - ",-1)),e(t,{href:"http://www.infoworld.com/article/3171682/internet-of-things/how-to-access-your-raspberry-pi-remotely-over-the-internet.html"},{default:a(()=>[...i[6]||(i[6]=[s("如何在你的计算机上启用 RealVNC",-1)])]),_:1}),i[8]||(i[8]=s("。",-1))]),i[25]||(i[25]=l("p",null,"在该系列的下一篇文章中，我将讲解使用你的树莓派去远程管理你的 3D 打印机。",-1)),i[26]||(i[26]=l("hr",null,null,-1)),l("p",null,[i[10]||(i[10]=s("via: ",-1)),e(t,{href:"https://www.infoworld.com/article/3176488/linux/a-beginner-s-guide-to-raspberry-pi-3.html"},{default:a(()=>[...i[9]||(i[9]=[s("https://www.infoworld.com/article/3176488/linux/a-beginner-s-guide-to-raspberry-pi-3.html",-1)])]),_:1})]),l("p",null,[i[14]||(i[14]=s("作者：",-1)),e(t,{href:"https://www.infoworld.com/author/Swapnil-Bhartiya/"},{default:a(()=>[...i[11]||(i[11]=[s("Swapnil Bhartiya",-1)])]),_:1}),i[15]||(i[15]=s(" 译者：",-1)),e(t,{href:"https://github.com/qhwdw"},{default:a(()=>[...i[12]||(i[12]=[s("qhwdw",-1)])]),_:1}),i[16]||(i[16]=s(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:a(()=>[...i[13]||(i[13]=[s("wxy",-1)])]),_:1})]),l("p",null,[i[19]||(i[19]=s("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[17]||(i[17]=[s("LCTT",-1)])]),_:1}),i[20]||(i[20]=s(" 原创编译，",-1)),e(t,{href:"https://linux.cn/"},{default:a(()=>[...i[18]||(i[18]=[s("Linux中国",-1)])]),_:1}),i[21]||(i[21]=s(" 荣誉推出",-1))])])}const w=n(g,[["render",h]]);export{y as __pageData,w as default};
